import java.net.*; import java.io.*; public class TestKC { public static void main(String[] args) throws Exception { URL url = new URL("https://connect.kingsch.at/developer/api/oauth2/token"); HttpURLConnection con = (HttpURLConnection) url.openConnection(); con.setRequestMethod("POST"); con.setRequestProperty("Content-Type", "application/json"); con.setDoOutput(true); String payload = "{\"grant_type\":\"authorization_code\",\"client_id\":\"f0b84963-573c-4cad-b0af-51f573f2f4e2\",\"code\":\"invalid_code\"}"; try (OutputStream os = con.getOutputStream()) { os.write(payload.getBytes()); } int status = con.getResponseCode(); System.out.println("Status: " + status); InputStream is = status < 400 ? con.getInputStream() : con.getErrorStream(); BufferedReader in = new BufferedReader(new InputStreamReader(is)); String inputLine; while ((inputLine = in.readLine()) != null) { System.out.println(inputLine); } in.close(); } }
